    stack = []
    for i in range(r):
        for j in range(c):
            if (i == 0 or j == 0 or i == r - 1 or j == c - 1) and g[i][j] == 'O':
                g[i][j] = 'S'
                stack.append((i, j))
    while stack:
        i, j = stack.pop()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < r and 0 <= b < c and g[a][b] == 'O':
                g[a][b] = 'S'
                stack.append((a, b))
    out = []
