def reaches_border(si, sj):
    seen = {(si, sj)}
    todo = [(si, sj)]
    while todo:
        i, j = todo.pop()
        if i == 0 or j == 0 or i == r - 1 or j == c - 1:
            return True
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if g[a][b] == 'O' and (a, b) not in seen:
                seen.add((a, b))
                todo.append((a, b))
    return False


out = []
for i in range(r):
    row = ''
    for j in range(c):
        if g[i][j] == 'O' and reaches_border(i, j):
            row += 'O'
        else:
            row += 'X'
    out.append(row)
